// MOSS-Image's prompt from the enhancer's reply: a caption as it is, or a layout compiled to the model's one-line
// form as OpenMOSS's compile_prompt.py does (boxes from the canvas's top-left in pixels, x then y, to boxes about its
// centre, y then x, their edges enclosed), scaled to the picture's 1024 x 1024. A reply that is neither is a caption.
const SIZE = 1024;
const raw = String(reply == null ? '' : reply).trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
const quoted = (t) => { const q = []; String(t).replace(/["\u201C]([^"\u201D]{1,60})["\u201D]/g, (all, x) => { q.push(x); return all; }); return q; };
const caption = (t) => ({ prompt: t, described: t, lettering: quoted(t), layout: false });
// (a reply a bracket or two short, as a language model sometimes ends one, closed before it is read)
const closed = (t) => {
  const open = [];
  let inString = false, escaped = false;
  for (const ch of t) {
    if (inString) { if (escaped) escaped = false; else if (ch === '\\') escaped = true; else if (ch === '"') inString = false; continue; }
    if (ch === '"') inString = true;
    else if (ch === '{') open.push('}');
    else if (ch === '[') open.push(']');
    else if (ch === '}' || ch === ']') open.pop();
  }
  return t + open.reverse().join('');
};
const read = (t) => { try { return JSON.parse(t); } catch { return null; } };
const at = raw.indexOf('{');
const draft = at < 0 ? null : read(raw.slice(at, raw.lastIndexOf('}') + 1)) || read(closed(raw.slice(at)));
if (draft && typeof draft.caption === 'string' && !Array.isArray(draft.items)) return caption(draft.caption);
if (!draft || !Array.isArray(draft.items) || !draft.summary || typeof draft.summary.caption !== 'string') {
  // (JSON that cannot be read: its captions as one, never the JSON itself)
  const said = [];
  raw.replace(/"caption"\s*:\s*"((?:[^"\\]|\\.)*)"/g, (all, c) => { said.push(c.replace(/\\"/g, '"')); return all; });
  return caption(at < 0 ? raw : said.join(' ') || raw);
}
const sx = SIZE / (Number(draft.width) || SIZE), sy = SIZE / (Number(draft.height) || SIZE);
const edge = (v) => Math.min(Math.max(v, 0), SIZE);
const items = [];
for (const it of draft.items) {
  if (!it || typeof it !== 'object' || !Array.isArray(it.bbox) || it.bbox.length !== 4 || typeof it.caption !== 'string' || !it.caption.trim()) continue;
  const text = typeof it.text === 'string' && it.text.trim() ? it.text : null;
  const label = ['object', 'character', 'text'].includes(it.label) ? it.label : text ? 'text' : 'object';
  if (label === 'text' && !text) continue;
  const [x1, y1, x2, y2] = it.bbox.map(Number);
  if (![x1, y1, x2, y2].every(Number.isFinite)) continue;
  const box = [Math.floor(edge(y1 * sy)) - SIZE / 2, Math.floor(edge(x1 * sx)) - SIZE / 2, Math.ceil(edge(y2 * sy)) - SIZE / 2, Math.ceil(edge(x2 * sx)) - SIZE / 2];
  if (!(box[0] < box[2] && box[1] < box[3])) continue;
  const item = { label, caption: it.caption };
  if (text) item.text = text;
  for (const k of ['tags', 'palette']) if (Array.isArray(it[k])) item[k] = it[k].filter((x) => typeof x === 'string');
  item.bbox = box;
  items.push(item);
}
if (!items.length) return caption(draft.summary.caption);
const summary = {};
for (const [k, v] of Object.entries(draft.summary)) if (['meta', 'canvas', 'caption', 'palette'].includes(k)) summary[k] = typeof v === 'string' && k !== 'caption' && k !== 'canvas' ? [v] : v;
const lettering = items.filter((i) => i.text).map((i) => i.text);
return {
  prompt: JSON.stringify({ summary, items, bbox_coord_space: 'abs_centralized', bbox_format: 'yxyx' }),
  described: [summary.caption, ...items.map((i) => (i.text ? `The text "${i.text}": ${i.caption}` : i.caption))].join('\n'),
  lettering,
  layout: true,
};

// What the reviewer is asked: the person's own request (the caption, or the layout described, is how it was put to the
// model)
const made = caption && typeof caption === 'object' ? caption.described : caption;
return `The person asked for: ${request}

The picture was made from this description: ${made}

Check the picture against what the person asked for.`;

// The prompt for this try: the enhanced one, and on a retry the last review's fix with it (a model told what to
// get right this time; the review read as the step before it left it, the loop's last try). In a layout the fix goes
// after its summary's caption, the layout kept whole.
const last = nodes.verdict;
const fix = attempt > 1 && last && typeof last.fix === 'string' ? last.fix.trim() : '';
const made = caption && typeof caption === 'object';
const base = made ? caption.prompt : caption;
if (!fix) return base;
if (made && caption.layout) {
  const layout = JSON.parse(base);
  layout.summary.caption = `${layout.summary.caption} ${fix}`;
  return JSON.stringify(layout);
}
return `${base}\n\n${fix}`;

data.systemPrompt:
You check a picture an image model made against what the person asked for. Reply with JSON alone, no prose and no code fence, in exactly this shape:
{"pass": true or false, "issues": ["each real problem, in a few words"], "fix": "one sentence saying what the picture must show instead, as an instruction to the painter, or empty", "background": "plain" (an empty, even background), "pattern" (a texture, or small shapes or copies repeated across it) or "scene" (a place, a wall, a table), "text": {"requested": [each word or phrase the request asks to be written in the picture, exactly as asked: lettering, never the things it shows], "found": [each word or phrase you can read in the picture, letter by letter, as many times as it is written there (at most 3)]}}
Pass when the picture shows what was asked: the subjects and how many, any text exactly as asked (read it letter by letter: a wrong, missing or extra letter is an issue), the colours, the setting and the style. Other text is an issue only where it gets in the way: garbled letters on or beside the text asked for, or any text at all on a picture meant to be clean (a logo, an icon, a product shot); the signs and labels a scene would have anyway, and a reflection's mirrored letters, are fine. A logo, an emblem or an icon is the flat design alone on its background: shown as a sign, on a wall, a package or a product, in a photo or a scene, it fails, and so does a background filled with a pattern or repeated small copies of the mark. Detail the request does not mention is not an issue. Fail only for a problem the person would notice. The text lists hold the words alone; leave them empty where there is no text.

